CREATE TABLE public.crm_labels (key text PRIMARY KEY, title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 100)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_labels TO authenticated; GRANT ALL ON public.crm_labels TO service_role; ALTER TABLE public.crm_labels ENABLE ROW LEVEL SECURITY; CREATE POLICY "staff read labels" ON public.crm_labels FOR SELECT TO authenticated USING (public.is_staff()); CREATE POLICY "leaders edit labels" ON public.crm_labels FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin()); ALTER TABLE public.partners ADD COLUMN region text, ADD COLUMN phone text, ADD COLUMN email text, ADD COLUMN address text, ADD COLUMN notes text, ADD COLUMN import_key text; CREATE UNIQUE INDEX partners_import_key_unique ON public.partners(import_key); ALTER TABLE public.leads ADD COLUMN agent_region text;